# Generated by manage.py generate_test_cases.
"""Focused scenarios for deterministic listener-to-target text transforms."""

from typing import Any

from django.contrib.contenttypes.models import ContentType
from django.core.exceptions import PermissionDenied, ValidationError

from bloomerp.form_behaviors.builtins.transform_text import TRANSFORM_TEXT
from bloomerp.form_behaviors.definition import (
    BehaviorAction,
    BehaviorConfig,
    BehaviorContext,
    BehaviorResult,
    FieldValueUpdate,
    FormBehavior,
)
from bloomerp.form_behaviors.execution import BehaviorExecutor
from bloomerp.models.application_field import ApplicationField
from bloomerp.models.definition import FieldLayout, LayoutItem, LayoutRow
from bloomerp.models.users.user_object_layout_preference import (
    UserObjectLayoutPreference,
)
from bloomerp.tests.base import (
    BehaviorActionScenario,
    BloomerpBehaviorActionTestCase,
    ExpectedBehaviorActionException,
)


class TestTransformTextAction(BloomerpBehaviorActionTestCase):
    """Verify every transform plus typing, eligibility, and executor boundaries."""

    action = TRANSFORM_TEXT
    auto_create_customers = False

    def _field(self, name: str) -> ApplicationField:
        """Resolve one customer field used by the transform fixtures."""
        return self.get_application_field(name)

    def _scenario(
        self,
        name: str,
        value: Any,
        transformation: str,
        expected: str,
    ) -> BehaviorActionScenario:
        """Build one exact listener-to-target transform scenario."""
        return BehaviorActionScenario(
            name=name,
            context=BehaviorContext(
                values={"first_name": value, "last_name": "Existing"},
                listener_field="first_name",
                target_field="last_name",
            ),
            listener=self._field("first_name"),
            target=self._field("last_name"),
            config={"transformation": transformation},
            expected_result=BehaviorResult(
                values=(FieldValueUpdate(field="last_name", value=expected),)
            ),
        )

    def get_test_scenarios(self) -> list[BehaviorActionScenario]:
        """Cover all nine stable transformation IDs and invalid/empty inputs."""
        scenarios = [
            self._scenario(
                "Uppercase uses Unicode-aware Python casing",
                "Straße café",
                "uppercase",
                "STRASSE CAFÉ",
            ),
            self._scenario(
                "Lowercase uses Unicode-aware Python casing",
                "ÄBC DÉF",
                "lowercase",
                "äbc déf",
            ),
            self._scenario(
                "Title case uses the standard Python word transformation",
                "élan vital",
                "title_case",
                "Élan Vital",
            ),
            self._scenario(
                "Sentence case uppercases the first code point and lowers the rest",
                "hELLO WÖRLD",
                "sentence_case",
                "Hello wörld",
            ),
            self._scenario(
                "Trim removes boundary whitespace without changing internal runs",
                "\talpha   beta\n",
                "trim",
                "alpha   beta",
            ),
            self._scenario(
                "Collapse whitespace normalizes Unicode whitespace runs",
                "  alpha\tbeta\n gamma\u2003delta  ",
                "collapse_whitespace",
                "alpha beta gamma delta",
            ),
            self._scenario(
                "Upper snake uses the ASCII slug base and collapsed underscores",
                "Café déjà--vu__now",
                "upper_snake_case",
                "CAFE_DEJA_VU_NOW",
            ),
            self._scenario(
                "Lower snake uses the ASCII slug base and collapsed underscores",
                "Café déjà--vu__NOW",
                "lower_snake_case",
                "cafe_deja_vu_now",
            ),
            self._scenario(
                "Slug uses Django ASCII transliteration",
                "Café déjà Vu!",
                "slug",
                "cafe-deja-vu",
            ),
            self._scenario(
                "None produces the empty text suggestion normalized by execution",
                None,
                "uppercase",
                "",
            ),
            self._scenario(
                "An empty string remains empty",
                "",
                "slug",
                "",
            ),
        ]
        common = {
            "listener": self._field("first_name"),
            "target": self._field("last_name"),
        }
        scenarios.extend(
            [
                BehaviorActionScenario(
                    name="Unknown transformation IDs are rejected by the config form",
                    context=BehaviorContext(
                        values={"first_name": "Text", "last_name": "Existing"},
                        listener_field="first_name",
                        target_field="last_name",
                    ),
                    config={"transformation": "unknown"},
                    expected_exception=ExpectedBehaviorActionException(ValidationError),
                    **common,
                ),
                BehaviorActionScenario(
                    name="Structured listener values are rejected instead of stringified",
                    context=BehaviorContext(
                        values={
                            "first_name": {"unexpected": True},
                            "last_name": "Existing",
                        },
                        listener_field="first_name",
                        target_field="last_name",
                    ),
                    config={"transformation": "uppercase"},
                    expected_exception=ExpectedBehaviorActionException(
                        ValidationError, "requires a string"
                    ),
                    **common,
                ),
            ]
        )
        return scenarios

    def _owner(self) -> UserObjectLayoutPreference:
        """Create a real layout whose listener uppercases into a short text target."""
        return UserObjectLayoutPreference.objects.create(
            user=self.admin_user,
            name="Transform text fixture",
            content_type=ContentType.objects.get_for_model(self.CustomerModel),
            layout=FieldLayout(
                rows=[
                    LayoutRow(
                        columns=2,
                        items=[
                            LayoutItem(
                                id="first_name",
                                config={
                                    "behaviors": BehaviorConfig(
                                        behaviors=[
                                            FormBehavior(
                                                id="uppercase-name",
                                                actions=[
                                                    BehaviorAction(
                                                        action="transform_text",
                                                        target_field="last_name",
                                                        config={
                                                            "transformation": "uppercase"
                                                        },
                                                    )
                                                ],
                                            )
                                        ]
                                    ).to_storage()
                                },
                            ),
                            LayoutItem(id="last_name"),
                        ],
                    )
                ]
            ).model_dump(mode="json"),
        )

    def test_listener_and_target_catalogs_include_only_editable_text_contracts(
        self,
    ) -> None:
        """Eligibility follows real model/form types rather than a single model name."""
        fields = ApplicationField.get_for_model(self.CustomerModel)
        listener_names = set(
            TRANSFORM_TEXT.get_listener_fields(fields).values_list("field", flat=True)
        )
        target_names = set(
            TRANSFORM_TEXT.get_target_fields(
                fields, self._field("first_name")
            ).values_list("field", flat=True)
        )
        for names in (listener_names, target_names):
            self.assertIn("first_name", names)
            self.assertIn("last_name", names)
            self.assertIn("description", names)
            self.assertNotIn("age", names)
            self.assertNotIn("date_joined", names)

    def test_executor_validates_length_without_mutating_input_or_persistence(
        self,
    ) -> None:
        """Target validation rejects overflow and a valid suggestion remains draft-only."""
        customer = self.CustomerModel.objects.create(
            first_name="Stored", last_name="Persisted", age=18
        )
        executor = BehaviorExecutor(self._owner(), self.admin_user, instance=customer)
        values = {"first_name": "draft", "last_name": "Persisted"}
        before = values.copy()
        result = executor.evaluate("first_name", values)
        self.assertEqual(
            result.values,
            (FieldValueUpdate(field="last_name", value="DRAFT"),),
        )
        self.assertEqual(values, before)
        customer.refresh_from_db()
        self.assertEqual(customer.last_name, "Persisted")

        values["first_name"] = "ß" * 60
        with self.assertRaises(ValidationError):
            executor.evaluate("first_name", values)

    def test_executor_enforces_target_write_authorization(self) -> None:
        """The transform cannot bypass the declared target's write boundary."""
        customer = self.CustomerModel.objects.create(
            first_name="Stored", last_name="Persisted", age=18
        )
        executor = BehaviorExecutor(self._owner(), self.admin_user, instance=customer)
        executor.write_fields.pop("last_name")
        with self.assertRaises(PermissionDenied):
            executor.evaluate(
                "first_name",
                {"first_name": "draft", "last_name": "Persisted"},
            )
